export const clientStyle = "/* Keep the existing Akari layout. Only adjust the requested controls. */\n#quote-form label:has([name=\"location\"]){display:none!important}\n#quote-form label:has([name=\"email\"]){grid-column:1 / -1}\n#quote-form [type=\"submit\"]:disabled{opacity:.65;cursor:wait}\n#quote-status[data-state=\"error\"]{color:#a52626;font-weight:600}\n#quote-status[data-state=\"success\"]{color:#23613b;font-weight:600}\n/* Separate corner controls and keep the form and keyboard unobstructed. */\n.office-whatsapp{bottom:calc(20px + env(safe-area-inset-bottom,0px))!important;left:22px!important;right:auto!important}\n.ej-mobile-utility{position:fixed!important;display:flex!important;align-items:center;justify-content:center;min-width:76px;min-height:52px;bottom:calc(20px + env(safe-area-inset-bottom,0px))!important;right:22px!important;left:auto!important}\nhtml.ej-mobile-editing :is(.office-whatsapp,.ej-mobile-utility),html.ej-gallery-open :is(.office-whatsapp,.ej-mobile-utility){opacity:0!important;visibility:hidden!important;pointer-events:none!important}\nbody.ej-brand-theme .mobile-quick-actions{display:none!important}\n@media(max-width:760px){\n .office-whatsapp{left:18px!important;right:auto!important}\n .ej-mobile-utility{right:18px!important;left:auto!important}\n .ej-mobile-dock{display:none!important}\n body.ej-brand-theme:has(#quote-form:focus-within) :is(.office-whatsapp,.ej-mobile-utility){opacity:0!important;visibility:hidden!important;pointer-events:none!important}\n}\n.ej-progress-hidden,.ej-scroll-percentage{display:none!important}\n";
